    const lang = (document.documentElement.lang === 'id') ? 'id' : 'en';
    const d = T[lang] || T.en;
    const file = lastDataset;
    const bar = document.createElement('div');
    bar.className = 'daa-undo';
    bar.setAttribute('role', 'status');
    const txt = document.createElement('span');
