      if (FOLLOWUP_HEADINGS.indexOf(headingText(el)) === -1) continue;
      if (el.closest('.daa-followup')) continue;
      let wrap = el.parentElement;
      while (wrap && wrap.children.length === 1) wrap = wrap.parentElement;
      if (!wrap) continue;
